#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 bool isItPossible(string word1,string word2){
  int a[26]={},b[26]={};for(char c:word1)++a[c-'a'];for(char c:word2)++b[c-'a'];
  int da=0,db=0;for(int i=0;i<26;++i){da+=a[i]>0;db+=b[i]>0;}
  for(int i=0;i<26;++i)for(int j=0;j<26;++j){
   if(!a[i]||!b[j])continue;
   if(i==j){if(da==db)return true;continue;}
   int na=da-(a[i]==1)+(a[j]==0),nb=db-(b[j]==1)+(b[i]==0);
   if(na==nb)return true;
  }
  return false;
 }
};
